Write-Host "=== Configuration des secrets GitHub ===\n"
$repo = "YOUR_GITHUB_USERNAME/daily-card-quest"   # <-- Remplacez par votre nom d'utilisateur GitHub\n\n# Authentification GitHub CLI (une seule fois)\nif (-Not (gh auth status 2>$null)) {\n    Write-Host "Authentification GitHub CLI requise..."\n    gh auth login\n}\n\n$secrets = @{\n    APPLE_ID                  = Read-Host "Apple ID (ex. ton_email@apple.com)"\n    FASTLANE_PASSWORD        = Read-Host "Fastlane password (ou app‑specific password)" -AsSecureString | ConvertFrom-SecureString\n    MATCH_PASSWORD            = Read-Host "Match encryption password" -AsSecureString | ConvertFrom-SecureString\n    APP_STORE_CONNECT_API_KEY = Read-Host "App Store Connect API key JSON (laisser vide si vous n’en avez pas)"\n}\n\nforeach ($name in $secrets.Keys) {\n    $value = $secrets[$name]\n    if ($value) {\n        gh secret set $name --repo $repo --body $value\n        Write-Host "✅ Secret $name ajouté"\n    }\n}\n
